package raider.dsl.lineage.proj

import zio.*
import zio.test.*

object LineageRendererSpec extends ZIOSpecDefault:

  private val header =
    "// Generated by Raider lineage projection (ADR-027). Do not edit — comparator detects edits.\n"

  private def viewOf(id: String, rs: Vector[NodeView]): LineageView =
    new LineageView:
      def runId: String = id
      def roots: Vector[NodeView] = rs

  // Tiny view: one ModelCall root with a ToolCall child, one Delegation root
  // with a nested Phase child (LIN2-C-01 golden source of truth).
  private val tinyView: LineageView =
    viewOf(
      "run-2026-10-10",
      Vector(
        NodeView(
          "m1",
          NodeKind.ModelCall("glm-5.3-flash", 1),
          None,
          Vector(
            NodeView(
              "t1",
              NodeKind.ToolCall("files.write", "Mutating"),
              Some("m1"),
              Vector.empty,
              Some("d-tool-1")
            )
          ),
          Some("d-model")
        ),
        NodeView(
          "d1",
          NodeKind.Delegation("worker"),
          None,
          Vector(
            NodeView(
              "p1",
              NodeKind.Phase("verify"),
              Some("d1"),
              Vector.empty,
              Some("d-phase")
            )
          ),
          Some("d-del")
        )
      )
    )

  private val golden: String =
    header +
      "object lineage_run_2026_10_10:\n" +
      "  // model(\"glm-5.3-flash\", round = 1) // data: d-model\n" +
      "    // tool(\"files.write\", recovery = \"Mutating\") // data: d-tool-1\n" +
      "  def delegation_worker(): Unit = // data: d-del\n" +
      "    def phase_verify(): Unit = () // data: d-phase\n" +
      "    ()\n"

  // Deep chain (L34): the tree shape of the frozen deep-tree golden — a phase
  // whose first child is a comment-only ModelCall, with a nested Delegation
  // whose children are comment-only too. The `= ` of a named def opens its
  // body region at the first NON-comment statement (comments never bind an
  // indentation width), so the closing `()` must start at a width the parser
  // has already bound: the delegation's closer keeps the children width (its
  // body has no non-comment statement, the region binds to the closer line
  // itself), and the phase's closer sits at the nested delegation def width —
  // NOT at the shallow children width, where dotc 3.9.0 rejects it with
  // "The start of this line does not match any of the previous indentation
  // widths" (W10 review finding, lane L30; verified against pinned dotc).
  private val deepChainView: LineageView =
    viewOf(
      "run-deep-001",
      Vector(
        NodeView(
          "n0",
          NodeKind.Phase("plan"),
          None,
          Vector(
            NodeView(
              "n1",
              NodeKind.ModelCall("mock-coder", 1),
              Some("n0"),
              Vector(
                NodeView(
                  "n2",
                  NodeKind.Delegation("worker"),
                  Some("n1"),
                  Vector(
                    NodeView(
                      "n3",
                      NodeKind.ModelCall("mock-coder", 1),
                      Some("n2"),
                      Vector(
                        NodeView(
                          "n4",
                          NodeKind.ToolCall("grep_search", "Idempotent"),
                          Some("n3"),
                          Vector.empty,
                          Some("d4")
                        )
                      ),
                      Some("d3")
                    )
                  ),
                  None
                )
              ),
              Some("d1")
            )
          ),
          None
        )
      )
    )

  private val deepChainGolden: String =
    header +
      "object lineage_run_deep_001:\n" +
      "  def phase_plan(): Unit =\n" +
      "    // model(\"mock-coder\", round = 1) // data: d1\n" +
      "      def delegation_worker(): Unit =\n" +
      "        // model(\"mock-coder\", round = 1) // data: d3\n" +
      "          // tool(\"grep_search\", recovery = \"Idempotent\") // data: d4\n" +
      "        ()\n" +
      "      ()\n"

  // Id-level cycle: distinct node instances whose ids repeat an ancestor id
  // (the tree projection of a graph that was not acyclic).
  private def cyclicView(): LineageView =
    viewOf(
      "run-cycle",
      Vector(
        NodeView(
          "a",
          NodeKind.Phase("A"),
          None,
          Vector(
            NodeView(
              "b",
              NodeKind.Phase("B"),
              Some("a"),
              Vector(
                NodeView(
                  "a",
                  NodeKind.Phase("A-child"),
                  Some("b"),
                  Vector.empty,
                  None
                )
              ),
              None
            )
          ),
          None
        )
      )
    )

  // A kind this revision cannot render: the NodeKind enum is closed, so a
  // null kind stands in for a foreign kind a future wire revision (new enum
  // case, WIRE-FREEZE wave-3) could decode. Exercises the defensive
  // UnknownKind branch (LIN2-C-02): typed error, never a MatchError or NPE.
  // The defensive branch is deliberately tested via Option.empty[NodeKind]
  // .orNull (not the DisableSyntax.null literal): orNull yields the same
  // null kind the renderer would see from a foreign decode, while keeping
  // scalafix DisableSyntax.noNulls green.
  private def foreignView(): NodeView =
    NodeView("u1", Option.empty[NodeKind].orNull, None, Vector.empty, None)

  def spec = suite("LineageProjection LIN-02C")(
    test("LIN2-C-01 golden tiny view renders byte-identical on repeat") {
      val first = LineageRenderer.render(tinyView)
      val second = LineageRenderer.render(tinyView)
      assertTrue(
        first == Right(golden),
        second == Right(golden),
        first.map(_.getBytes("UTF-8").toSeq) == Right(
          golden.getBytes("UTF-8").toSeq
        )
      )
    },
    test(
      "L34-01: deep chain (comment-only ancestors) renders closers inside the def's bound region, byte-identical on repeat"
    ) {
      val first = LineageRenderer.render(deepChainView)
      val second = LineageRenderer.render(deepChainView)
      assertTrue(
        first == Right(deepChainGolden),
        second == Right(deepChainGolden),
        first.map(_.getBytes("UTF-8").toSeq) == Right(
          deepChainGolden.getBytes("UTF-8").toSeq
        )
      )
    },
    test("LIN2-C-02 foreign node kind → RenderError.UnknownKind") {
      val view = viewOf(
        "run-unknown",
        Vector(foreignView())
      )
      val result = LineageRenderer.render(view)
      val unknown = result.left.toOption.exists {
        case RenderError.UnknownKind(detail) => detail.nonEmpty
        case _                               => false
      }
      assertTrue(unknown)
    },
    test("empty graph → RenderError.Empty") {
      assertTrue(
        LineageRenderer.render(viewOf("run-empty", Vector.empty)) == Left(
          RenderError.Empty
        )
      )
    },
    test("id-level cycle → RenderError.Cyclic(repeated id)") {
      assertTrue(
        LineageRenderer.render(cyclicView()) == Left(RenderError.Cyclic("a"))
      )
    },
    test("duplicate def names are disambiguated deterministically") {
      val view = viewOf(
        "run-dup",
        Vector(
          NodeView("p1", NodeKind.Phase("verify"), None, Vector.empty, None),
          NodeView("p2", NodeKind.Phase("verify"), None, Vector.empty, None)
        )
      )
      val expected =
        header +
          "object lineage_run_dup:\n" +
          "  def phase_verify(): Unit = ()\n" +
          "  def phase_verify_2(): Unit = ()\n"
      assertTrue(LineageRenderer.render(view) == Right(expected))
    },
    test("LIN2-C-03 concurrent renders are identical and state-isolated") {
      val views = List.fill(8)(tinyView) ++ List.fill(8)(cyclicView())
      ZIO.foreachPar(views)(v => ZIO.succeed(LineageRenderer.render(v))).map {
        results =>
          val (rights, lefts) = results.partition(_.isRight)
          assertTrue(
            rights == List.fill(8)(Right(golden)),
            lefts == List.fill(8)(Left(RenderError.Cyclic("a")))
          )
      }
    },
    test(
      "W9F4-01: model/tool names with \n and \r keep every comment single-line"
    ) {
      // Pre-fix escape handled only `\` and `"`, so a raw newline inside a
      // model/tool/recovery name split the `//` comment (and the generated
      // artifact) into broken lines. The fixed discipline neutralizes \n, \r,
      // \t and other C0 controls exactly like the runtime GraphHash esc.
      val view = viewOf(
        "run-hostile",
        Vector(
          NodeView(
            "m1",
            NodeKind.ModelCall("gpt\n5\r-x\u0001", 1),
            None,
            Vector(
              NodeView(
                "t1",
                NodeKind.ToolCall("tool\tname\n2", "line\rbreak"),
                Some("m1"),
                Vector.empty,
                None
              )
            ),
            None
          )
        )
      )
      val expected =
        header +
          "object lineage_run_hostile:\n" +
          "  // model(\"gpt\\n5\\r-x\\x01\", round = 1)\n" +
          "    // tool(\"tool\\tname\\n2\", recovery = \"line\\rbreak\")\n"
      val rendered = LineageRenderer.render(view)
      assertTrue(
        rendered == Right(expected),
        rendered.toOption.exists(out => out.linesIterator.length == 4)
      )
    },
    test("W9F4-01: data ref with \n stays on its comment line") {
      val view = viewOf(
        "run-ref",
        Vector(
          NodeView(
            "p1",
            NodeKind.Phase("verify"),
            None,
            Vector.empty,
            Some("d\nref")
          )
        )
      )
      val expected =
        header +
          "object lineage_run_ref:\n" +
          "  def phase_verify(): Unit = () // data: d\\nref\n"
      assertTrue(LineageRenderer.render(view) == Right(expected))
    }
  )
